      const templates=document.createElement('section');templates.className='templates';templates.innerHTML='<h3>Шаблоны</h3><label class="field">Макет<select data-template><option value="climate-comfort">Климат и комфорт</option><option value="blank">Пустая панель</option></select></label><button data-cmd="apply-template">Применить шаблон</button><p class="hint">Заменит макет и очистит привязки устройств. Можно отменить стрелкой назад.</p>';
      this.dialog.querySelector('.palette h3').before(templates);
      this.dialog.querySelector('.toolbar [data-cmd="undo"]').remove();this.dialog.querySelector('.toolbar [data-cmd="redo"]').remove();
      const historyBar=document.createElement('div');historyBar.className='history-actions';historyBar.innerHTML='<div><button data-cmd="undo" aria-label="Отменить действие">← Отменить</button><button data-cmd="redo" aria-label="Вернуть отменённое действие">Вернуть →</button></div><small data-history-info aria-live="polite">Нет изменений</small>';this.dialog.querySelector('.top-actions').before(historyBar);
      const tabs=document.createElement('nav');tabs.className='page-tabs';tabs.setAttribute('aria-label','Экраны и меню');this.dialog.querySelector('.topbar').after(tabs);
      this.dialog.querySelector('.toolbar').insertAdjacentHTML('beforeend','<label>Масштаб <select data-zoom><option value="fit">По окну</option><option value="1">100%</option><option value="1.25">125%</option><option value="1.5" selected>150%</option><option value="2">200%</option></select></label>');
      this.dialog.querySelector('[data-zoom]').onchange=e=>{const wrap=this.dialog.querySelector('.canvas-wrap');wrap.style.width=e.target.value==='fit'?'min(100%,calc(100dvh - 310px))':`min(100%,${480*Number(e.target.value)}px)`;};
