      this.dialog.addEventListener('focusin',e=>{const input=e.composedPath().find(n=>n?.dataset?.field&&['INPUT','TEXTAREA'].includes(n.tagName));if(input)input.dataset.historyValue=input.value;});
      this.dialog.addEventListener('change',e=>{const input=e.composedPath().find(n=>n?.dataset?.field&&['INPUT','TEXTAREA'].includes(n.tagName));if(input){input.dataset.historyValue=input.value;if(this.pendingInput===input)this.pendingInput=null;}},true);
      this.dialog.addEventListener('pointerdown',e=>{if(e.target.closest('[data-cmd="undo"],[data-cmd="redo"]'))this.flushInput();},true);
      this.dialog.querySelector('[data-snap]').onchange=e=>{this.snap=Number(e.target.value);this.renderCanvas();};
      this.dialog.querySelector('[data-file]').onchange=e=>this.importFile(e.target.files[0]);
