      if(this.currentPage?.kind==='menu')canvas.insertAdjacentHTML('beforeend',`<div class="editor-menu-bar">← ${esc(this.currentPage.title)}</div>`);
      canvas.querySelectorAll('[data-widget-id]').forEach(el=>{const w=this.widgets.find(w=>w.id===el.dataset.widgetId);if(!w.visible)el.classList.add('editor-hidden');el.classList.toggle('selected',w.id===this.selected);if(w.id===this.selected){el.insertAdjacentHTML('beforeend',`<span class="selection-label">${esc(TYPES[w.type])} · ${Math.round(w.w)} × ${Math.round(w.h)}</span>${['nw','ne','sw','se'].map(h=>`<span class="resize-handle ${h}" data-handle="${h}"></span>`).join('')}`);}});
