      if(!w){this.renderScreen(box);return;}
      box.innerHTML=`<h3>${esc(TYPES[w.type])}</h3><div class="widget-actions"><button data-cmd="duplicate" title="Копировать элемент">Копия</button><button data-cmd="down" title="На слой ниже">↓ Слой</button><button data-cmd="up" title="На слой выше">↑ Слой</button><button data-cmd="delete" class="danger">Удалить</button></div>${this.field('label','Название',w.label)}${w.type==='text'?`<label class="field">Текст<textarea data-field="text">${esc(w.text??w.label??'')}</textarea></label>`:''}${w.type==='header'?this.field('subtitle','Подпись',w.subtitle??'Климат и комфорт'):''}<div class="ha-selectors"></div><h4>Положение и размер, px</h4><div class="fields-2">${['x','y','w','h'].map((k,i)=>this.field(k,['Отступ слева','Отступ сверху','Ширина','Высота'][i],w[k],'number',`min="${i<2?0:32}" max="480" step="${this.snap}"`)).join('')}</div><h4>Оформление</h4><div class="fields-2">${this.field('font_size','Размер текста',w.font_size,'number','min="8" max="120"')}${this.field('label_size','Размер подписи',w.label_size,'number','min="8" max="48"')}${this.field('icon_size','Размер значка',w.icon_size,'number','min="8" max="96"')}${this.field('radius','Скругление',w.radius,'number','min="0" max="80"')}</div><div class="fields-2">${this.field('background','Фон',w.background,'color')}${this.field('color','Цвет текста',w.color,'color')}${this.field('icon_color','Цвет значка',w.icon_color,'color')}</div>${w.type==='sensor'?`<div class="fields-2">${this.field('unit','Единица',w.unit??'')}${this.field('decimals','Знаков после запятой',w.decimals??0,'number','min="0" max="3"')}</div>`:''}<label class="check"><input type="checkbox" data-field="visible" ${w.visible?'checked':''}> Показывать на панели</label><p class="hint">Предпросмотр показывает данные HA. Управление устройствами здесь отключено.</p>`;
      box.querySelectorAll('[data-field]').forEach(input=>input.onchange=()=>{this.remember(null,this.fieldAction(input.dataset.field));const key=input.dataset.field;w[key]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;if(w.type==='service_title'&&key==='label')this.draft.service_menu.title=w[key];Object.assign(w,normalizeWidget(w));box.querySelectorAll('input[type="number"][data-field]').forEach(field=>{if(w[field.dataset.field]!=null)field.value=w[field.dataset.field];});this.renderCanvas();this.syncEditorLabels();this.renderHistory();});
      if(REQUIRED_SERVICE_TYPES.includes(w.type)){box.querySelector('[data-cmd="delete"]').disabled=true;box.querySelector('[data-cmd="duplicate"]').disabled=true;box.querySelector('[data-field="visible"]').disabled=true;const hint=document.createElement('p');hint.className='hint';hint.textContent='Системный элемент киоска: положение, размер и оформление редактируются. Он остаётся доступным в служебном меню.';box.querySelector('.widget-actions').after(hint);}
